## 3️⃣ Pure‑HTML UI + Any Geocoder (you wire the results yourself)

If you prefer a **lighter UI** (or you already have a search box in your design), you can skip the bundled UI entirely:

```html
<input id="search" type="text" placeholder="Search…" />
<ul id="results" style="position:absolute;z-index:10;background:#fff;"></ul>
```

```js
const input = document.getElementById('search');
const resultsEl = document.getElementById('results');

let abortCtrl = null;

input.addEventListener('input', async (e) => {
  const q = e.target.value.trim();
  if (!q) { resultsEl.innerHTML = ''; return; }

  // Cancel previous request
  if (abortCtrl) abortCtrl.abort();
  abortCtrl = new AbortController();

  const url = new URL('https://photon.komoot.io/api/');
  url.search = new URLSearchParams({ q, limit: 5 });

  const resp = await fetch(url, { signal: abortCtrl.signal });
  const data = await resp.json();

  resultsEl.innerHTML = data.features
    .map(f => `<li data-lng="${f.geometry.coordinates[0]}" data-lat="${f.geometry.coordinates[1]}">${f.properties.name || f.properties.street || f.properties.country}</li>`)
    .join('');
});

resultsEl.addEventListener('click',
